import{_ as o,l,o as e,c as s,v as t,p as n,x as r,d as E,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"掩模配准","description":"","frontmatter":{"title":"掩模配准","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/mask-registration.md","filePath":"litho/mask-registration.md","lastUpdated":1789023840000}'),p={name:"litho/mask-registration.md"};function m(c,a,_,A,B,u){const i=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="掩模配准" tabindex="-1">掩模配准 <a class="header-anchor" href="#掩模配准" aria-label="Permalink to &quot;掩模配准&quot;">​</a></h1><div class="epigraph"><p>配准是版上图形相对理想格子的放置误差；缩小倍率之后它直接进入晶圆套刻，不能等扫描机再「对准掉」。</p><footer>—— 对照 mask registration / image placement 与套刻预算分摊的通称</footer></div><p><a href="/litho/mask-cdu">上一课</a>把尺寸指纹收成 CDU。缺口是中心线放在哪：写场拼接、充电偏转、基板应力、台镜都会让图形离开设计格子。本课钉掩模配准。数据课序到此收束；下一课序从<a href="/litho/mask-blank-ltem">坯与 LTEM</a> 换到物理基板。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>扫描机对准的是掩模对准键相对晶圆标记。键本身若相对芯片阵列有放置误差，或阵列内部相对键有畸变，套刻正确数仍会印错。配准（registration / image placement）度量的就是这张版坐标系误差。\\(4\\times\\) 光学把版上误差除以四落到晶圆（anamorphic 则按轴），但仍占 overlay 预算的一截，尤其多重图形同层两张版的相对配准。</p><p>缺口是<strong>放置</strong>，不是再量一次 CD。把套刻超差全部写成扫描机或晶圆应力，会漏掉掩模厂的格子。</p><h3 id="两张版的相对配准" tabindex="-1">两张版的相对配准 <a class="header-anchor" href="#两张版的相对配准" aria-label="Permalink to &quot;两张版的相对配准&quot;">​</a></h3><p>LELE 或切线层的两张掩模若配准指纹不相关，同层套刻会多一项「版对版」。配对写、配对计量、甚至规定同一写入器，是产线对策，不是光学 RET。</p><p><span class="marginnote">EUV 反射掩模的夹持与背面颗粒会改面形，从而改投影配准。计量要声明夹持状态是否与扫描机一致。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>掩模配准工具（光学衍射或专用配准仪）在版上测标记阵列，拟合平移、旋转、放大、正交，以及高阶多项式。可校正项写入扫描机掩模校正文件；不可校正残差进 overlay 预算。写模侧：场拼接校准、充电补偿、热模型与基板选择（下一课 LTEM）一起压残差。</p><p>与 CDU 的分工：CDU 是宽度，配准是中心。充电可以同时改两者：落点偏了是配准，局部剂量变了是 CD。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>电子束在绝缘或充电胶上积累电荷，束被偏转，放置随写顺序变——所以写策略（从内向外、接地层）是配准工艺。LTEM 基板减的是曝光热致膨胀；普通石英在写束热负载下格子会漂。投影到晶圆时，扫描机可以吃低阶（放大、旋转），吃不干净写场拼接的高频拼接缝。</p>',14)),(e(),n(h,null,{default:r(()=>[d(i,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20WRITE%5B%22%E6%8B%BC%E6%8E%A5%20%2F%20%E5%85%85%E7%94%B5%20%2F%20%E7%83%AD%22%5D%20--%3E%20REG%5B%22mask%20registration%22%5D%0A%20%20CLAMP%5B%22%E5%A4%B9%E6%8C%81%E4%B8%8E%E9%9D%A2%E5%BD%A2%22%5D%20--%3E%20REG%0A%20%20REG%20--%3E%20LOW%5B%22%E6%89%AB%E6%8F%8F%E6%9C%BA%E5%8F%AF%E6%A0%A1%E6%AD%A3%E4%BD%8E%E9%98%B6%22%5D%0A%20%20REG%20--%3E%20RES%5B%22%E6%AE%8B%E5%B7%AE%E8%BF%9B%20overlay%22%5D%0A%20%20RES%20--%3E%20OL%5B%22%E6%99%B6%E5%9C%86%E5%A5%97%E5%88%BB%E9%A2%84%E7%AE%97%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>配准不修复吸收体缺陷。高阶校正若每张版不同，扫描机配方管理会膨胀——这是控制课的伏笔，本课只钉误差来源。不编造 nm 规格表。</p><p>后课序默认：数据与写入误差已有语言（CDU、配准、炮数）；下一课问基板本身是什么玻璃、为什么热胀系数要低。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>掩模配准是图形放置误差，经倍率进入晶圆套刻。</li><li>同层多张版的相对配准是多重图形的隐藏项。</li><li>低阶可进扫描机校正；拼接与充电残差往往不可完全吃掉。</li><li>出处：mask registration 与 overlay 分摊通称；写模充电/拼接公开讨论。</li></ul>',5))])}const D=o(p,[["render",m]]);export{k as __pageData,D as default};
